import { describe, it, expect } from 'vitest';
import { GoldenConfigDriftEngine } from '../src/config-drift.js';

describe('GoldenConfigDriftEngine Detection', () => {
  it('should clean comments and timestamps from raw config text', () => {
    const raw = `
# Generated by RouterOS 7.15.2
# Last configuration change: Oct 10 2026 08:00:00
/interface bridge add name=bridge1
! Cisco comment line
// Another comment
/ip address add address=192.168.1.1/24 interface=bridge1
`;

    const cleaned = GoldenConfigDriftEngine.cleanConfigLines(raw);
    expect(cleaned).toHaveLength(2);
    expect(cleaned).toContain('/interface bridge add name=bridge1');
    expect(cleaned).toContain('/ip address add address=192.168.1.1/24 interface=bridge1');
  });

  it('should report IN_SYNC with 100% score when running config matches baseline', () => {
    const baseline = `
/interface bridge add name=bridge1
/ip address add address=10.0.0.1/24 interface=bridge1
`;
    const running = baseline;

    const result = GoldenConfigDriftEngine.detectDrift(running, baseline);
    expect(result.isDrifted).toBe(false);
    expect(result.driftScore).toBe(100);
    expect(result.severity).toBe('IN_SYNC');
    expect(result.discrepancies).toHaveLength(0);
  });

  it('should detect unauthorized shadow changes and lower score', () => {
    const baseline = `
/interface bridge add name=bridge1
/ip address add address=10.0.0.1/24 interface=bridge1
`;
    const running = `
/interface bridge add name=bridge1
/ip address add address=10.0.0.1/24 interface=bridge1
/ip firewall nat add action=masquerade chain=srcnat out-interface=ether1
`;

    const result = GoldenConfigDriftEngine.detectDrift(running, baseline);
    expect(result.isDrifted).toBe(true);
    expect(result.driftScore).toBeLessThan(100);
    expect(result.addedLinesCount).toBe(1);
    expect(result.discrepancies.some((d) => d.type === 'UNAUTHORIZED_ADDITION')).toBe(true);
  });
});
